<bs2-ds-feedback status='attention' [title]='title' [message]='message' /><br/>
<bs2-ds-feedback status='error' [title]='title' [message]='message' /><br/>
<bs2-ds-feedback status='success' [title]='title' [message]='message' />
      `,
    };
