    template: `
      ${boxStyle}
      <h3>(Default Max Column:12) (Default Gap: 30px)</h3>
      <div bs2-ds-row>
        ${column(1, [12])}
        ${column(2, [6])}
        ${column(3, [4])}
        ${column(4, [3])}
        ${column(6, [2])}
