{
  render: () => {
    const control = new FormControl([]);
    const options = [
      { id: 1, text: 'Banana' },
      { id: 2, text: 'Maça' },
      { id: 3, text: 'Uva' },
    ];

    const emitter = () => {
      if (control.value.length === options.length) return control.setValue([]);
      if (control.value.length >= 0) return control.setValue(options.map((item) => item.id));
    };

    return {
      props: {
        control,
        options,
        emitter,
      },
      template: `
